"use client";
import { useState } from "react";
import { EosAppGlyph, type EosAppKind } from "@/components/application/eos/glyphs";
import { EosAppShell } from "@/components/application/eos/app-shell";
import { EosSegmentedControl } from "@/components/application/eos/segmented-control";

const INSTALLED: { title: string; text: string; when: string; apps: EosAppKind[] }[] = [
  { title: "Morning brief", text: "Calendar, inbox and weather in one note at 7:00.", when: "Every day at 7:00", apps: ["calendar", "mail"] },
  { title: "Invoice nudge", text: "Chases unpaid invoices kindly after 14 days.", when: "Daily", apps: ["books", "mail"] },
  { title: "Standup digest", text: "Yesterday's updates in one post.", when: "Weekdays at 9:30", apps: ["chat", "docs"] },
];

const card = { display: "grid", gap: 8, padding: "18px 20px", borderRadius: 20, border: "1px solid var(--eos-hairline)", background: "var(--eos-card)" } as const;

/** The charcoal shell on its Routines page. Narrow the frame below 720 px and the sidebar becomes a drawer. */
export default function EosAppShellDemo() {
  const [tab, setTab] = useState("installed");
  return (
    <EosAppShell height={640} style={{ width: "100%", borderRadius: 18 }}>
      <div style={{ boxSizing: "border-box", maxWidth: 680, margin: "0 auto", padding: "40px 24px" }}>
        <h2 style={{ margin: 0, fontSize: 28, fontWeight: 550, letterSpacing: "-0.02em", color: "var(--eos-text)" }}>Routines</h2>
        <p style={{ margin: "6px 0 22px", fontSize: 16, color: "var(--eos-text-secondary)" }}>Run the work you repeat</p>
        <EosSegmentedControl
          label="Routines"
          segments={[
            { value: "installed", label: "Installed" },
            { value: "discover", label: "Discover" },
          ]}
          value={tab}
          onChange={setTab}
        />
        <ul style={{ display: "grid", gap: 12, margin: "24px 0 0", padding: 0, listStyle: "none" }}>
          {tab === "installed" ? (
            INSTALLED.map((r) => (
              <li key={r.title} style={card}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  {r.apps.map((app) => (
                    <EosAppGlyph key={app} app={app} size={20} />
                  ))}
                  <b style={{ fontWeight: 500, color: "var(--eos-text)" }}>{r.title}</b>
                  <span style={{ marginLeft: "auto", fontSize: 14, color: "var(--eos-text-tertiary)" }}>{r.when}</span>
                </div>
                <span style={{ fontSize: 15, color: "var(--eos-text-secondary)" }}>{r.text}</span>
              </li>
            ))
          ) : (
            <li style={card}>
              <b style={{ fontWeight: 500, color: "var(--eos-text)" }}>Weekly cash summary</b>
              <span style={{ fontSize: 15, color: "var(--eos-text-secondary)" }}>Adds up last week&apos;s paid invoices every Monday and posts the total in #finance.</span>
              <span style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14.5, color: "var(--eos-text-tertiary)" }}>
                by <EosAppGlyph app="books" size={18} /> <b style={{ fontWeight: 450, color: "var(--eos-text)" }}>Coffer</b>
              </span>
            </li>
          )}
        </ul>
      </div>
    </EosAppShell>
  );
}

