"use client";
/**
 * EosAppShell: the charcoal app shell. A sidebar with a workspace switcher, search and collapse, a Home and Activity
 * segmented control, a nav list with line icons, an active row, and labelled sections with an unread dot; a top bar
 * with the page title; and a content slot. Below 720 px of its own width the sidebar becomes a drawer behind a menu
 * button in the top bar. EosAppSidebar is the sidebar on its own, for a page that is itself the app.
 *
 * Motion (motion.ts): the active row is the shared Eos indicator, sliding to the row chosen; rows and buttons answer
 * hover with a wash that fades in and press with a small settle. Collapsing slides the sidebar away while the main
 * area glides into its place; the drawer slides in over a fading scrim with its shadow fading in. Menus open with a
 * short drop, and a working row's spinner turns only while it shows.
 */
import {
  RiBarChart2Line,
  RiBookOpenLine,
  RiChat3Line,
  RiCheckLine,
  RiExpandUpDownLine,
  RiFileTextLine,
  RiFlashlightLine,
  RiFolder3Line,
  RiLayoutMasonryLine,
  RiMenuLine,
  RiRocket2Line,
  RiSearchLine,
  RiSideBarLine,
  RiSparkling2Line,
  RiTableLine,
} from "@remixicon/react";
import { useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from "react";
import { EosAppGlyph, EosMark, type EosAppKind } from "./glyphs";
import { eosCanAnimate, eosEaseCss, EosIndicator, eosMotion, eosRiseStyle, useEosIndicator, useEosLoop } from "./motion";
import { EosSegmentedControl, type EosSegment } from "./segmented-control";
import { cx, rovingIndex, SR_ONLY_CSS, useControlled, useIsoLayoutEffect } from "./shared";
import { EosScope, useEosTheme } from "./theme";
import type { EosMode } from "./tokens";

export interface EosNavItem {
  id: string;
  label: string;
  icon?: ReactNode;
  /** A trailing signal: a spinner while it works, an unread dot, or a count. */
  badge?: "spinner" | "dot" | number;
  href?: string;
}
export interface EosNavSection {
  id: string;
  label?: string;
  items: readonly EosNavItem[];
}
export interface EosWorkspace {
  id: string;
  name: string;
  mark?: ReactNode;
}
export interface EosActivityItem {
  id: string;
  app: EosAppKind;
  text: string;
  time: string;
}

const ICON = { size: 18 } as const;

export const EOS_SHELL_WORKSPACES: readonly EosWorkspace[] = [
  { id: "morrow", name: "Morrow", mark: <EosMark kind="sun" size={22} /> },
  { id: "personal", name: "Personal", mark: <EosMark kind="ring" size={22} /> },
];

export const EOS_SHELL_TABS: readonly EosSegment[] = [
  { value: "home", label: "Home" },
  { value: "activity", label: "Activity" },
];

export const EOS_SHELL_SECTIONS: readonly EosNavSection[] = [
  {
    id: "main",
    items: [
      { id: "start", label: "Get started", icon: <RiRocket2Line {...ICON} />, badge: "spinner" },
      { id: "assistant", label: "Assistant", icon: <RiSparkling2Line {...ICON} /> },
      { id: "sheets", label: "Sheets", icon: <RiTableLine {...ICON} /> },
      { id: "documents", label: "Documents", icon: <RiFileTextLine {...ICON} /> },
      { id: "insights", label: "Insights", icon: <RiBarChart2Line {...ICON} /> },
      { id: "routines", label: "Routines", icon: <RiFlashlightLine {...ICON} /> },
      { id: "boards", label: "Boards", icon: <RiLayoutMasonryLine {...ICON} /> },
      { id: "library", label: "Library", icon: <RiBookOpenLine {...ICON} /> },
    ],
  },
  {
    id: "projects",
    label: "Projects",
    items: [
      { id: "spring-launch", label: "Spring launch", icon: <RiFolder3Line {...ICON} />, badge: "dot" },
      { id: "hiring", label: "Hiring", icon: <RiFolder3Line {...ICON} /> },
    ],
  },
  {
    id: "chat",
    label: "Chat",
    items: [
      { id: "finance", label: "#finance", icon: <RiChat3Line {...ICON} /> },
      { id: "launch", label: "#launch", icon: <RiChat3Line {...ICON} /> },
    ],
  },
];

export const EOS_SHELL_ACTIVITY: readonly EosActivityItem[] = [
  { id: "a1", app: "books", text: "Invoice nudge sent 3 reminders", time: "2m" },
  { id: "a2", app: "chat", text: "Standup digest posted in #launch", time: "9:30" },
  { id: "a3", app: "calendar", text: "Morning brief is ready", time: "7:00" },
  { id: "a4", app: "sheet", text: "Lead scout added 12 leads", time: "Mon" },
];

