`;

/** A working row's spinner: it turns only while it shows. */
function Spinner() {
  const spin = useRef<HTMLSpanElement>(null);
  useEosLoop(spin);
  return <span ref={spin} className="eos-spin" aria-hidden />;
}

export interface EosAppSidebarProps {
  workspaces?: readonly EosWorkspace[];
  workspace?: string;
  defaultWorkspace?: string;
  onWorkspaceChange?: (id: string) => void;
  tabs?: readonly EosSegment[];
  tab?: string;
  defaultTab?: string;
  onTabChange?: (value: string) => void;
  sections?: readonly EosNavSection[];
  active?: string;
  defaultActive?: string;
  onNavigate?: (id: string) => void;
  /** What the second tab lists. */
  activity?: readonly EosActivityItem[];
  /** The button beside search: collapse the sidebar, or close it as a drawer. Without it there is no button. */
  onCollapse?: () => void;
  collapseLabel?: string;
  /** Escape with no menu or search open, e.g. to close a drawer. */
  onEscape?: () => void;
  className?: string;
  style?: CSSProperties;
}

/**
 * The sidebar on its own: the workspace switcher, search, the Home and Activity control, and the nav or the recent
 * activity. The shell holds it in its aside; a page that is itself the app can hold it in a rail of its own.
 */
export function EosAppSidebar({
  workspaces = EOS_SHELL_WORKSPACES,
  workspace,
  defaultWorkspace,
  onWorkspaceChange,
  tabs = EOS_SHELL_TABS,
  tab,
  defaultTab,
  onTabChange,
  sections = EOS_SHELL_SECTIONS,
  active,
  defaultActive = "routines",
  onNavigate,
  activity = EOS_SHELL_ACTIVITY,
  onCollapse,
  collapseLabel = "Collapse sidebar",
  onEscape,
  className,
  style,
}: EosAppSidebarProps) {
  const [ws, setWs] = useControlled(workspace, defaultWorkspace ?? workspaces[0]?.id ?? "", onWorkspaceChange);
  const [view, setView] = useControlled(tab, defaultTab ?? tabs[0]?.value ?? "", onTabChange);
  const [current, setCurrent] = useControlled(active, defaultActive, onNavigate);
  const [menu, setMenu] = useState(false);
  const [query, setQuery] = useState<string | null>(null);
  const wsBox = useRef<HTMLDivElement>(null);
  const wsButton = useRef<HTMLButtonElement>(null);
  const options = useRef<(HTMLButtonElement | null)[]>([]);
  const nav = useRef<HTMLElement>(null);
  const navActive = useRef<HTMLSpanElement>(null);
  const rows = useRef(new Map<string, HTMLElement>());
  // Rows rise in when the reader switches between the nav and the activity, not on load.
  const [switched, setSwitched] = useState(false);
  const look = useEosTheme()?.look;
  const chosen = workspaces.find((w) => w.id === ws) ?? workspaces[0];

  useEffect(() => {
    if (!menu) return;
    const close = (event: PointerEvent) => {
      if (!(event.target instanceof Node) || !wsBox.current?.contains(event.target)) setMenu(false);
    };
    document.addEventListener("pointerdown", close);
    const index = Math.max(
      0,
      workspaces.findIndex((w) => w.id === ws),
    );
    options.current[index]?.focus();
    return () => document.removeEventListener("pointerdown", close);
  }, [menu, workspaces, ws]);

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key !== "Escape") return;
    if (menu) {
      setMenu(false);
      wsButton.current?.focus();
    } else if (query !== null) setQuery(null);
    else onEscape?.();
  };
  const onOptionKey = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = rovingIndex(event.key, index, workspaces.length);
    if (next < 0) return;
    event.preventDefault();
    options.current[next]?.focus();
  };

  const needle = query?.trim().toLowerCase() ?? "";
  useEosIndicator({ host: nav, indicator: navActive, target: () => rows.current.get(current), choice: current, look });
  const motion = eosMotion(look);
  const rise = (index: number) => (switched ? { className: "eos-rise", style: eosRiseStyle(index, motion) } : {});
  const shown = sections
    .map((section) => ({ ...section, items: section.items.filter((item) => !needle || item.label.toLowerCase().includes(needle)) }))
    .filter((section) => section.items.length > 0);
  const badge = (item: EosNavItem) =>
    item.badge === "spinner" ? (
      <Spinner />
    ) : item.badge === "dot" ? (
      <span className="eos-unread">
        <span className="eos-sr">, unread</span>
      </span>
    ) : typeof item.badge === "number" ? (
      <span className="eos-count">{item.badge}</span>
    ) : null;
  const row = (id: string) => (el: HTMLElement | null) => {
    if (el) rows.current.set(id, el);
    else rows.current.delete(id);
  };

  return (
    <EosScope>
    <div className={cx("eos-side-inner", className)} style={style} onKeyDown={onKeyDown}>
      <style>{CSS}</style>
      <div className="eos-side-head">
        <div ref={wsBox} className="eos-ws">
          <button ref={wsButton} type="button" className="eos-ws-btn" aria-haspopup="menu" aria-expanded={menu} onClick={() => setMenu((open) => !open)}>
            {chosen?.mark}
            <span className="eos-ws-name">{chosen?.name}</span>
            <RiExpandUpDownLine size={16} aria-hidden />
          </button>
          {menu && (
            <div className="eos-ws-menu" role="menu" aria-label="Workspaces">
              {workspaces.map((w, index) => (
                <button
                  key={w.id}
                  ref={(el) => {
                    options.current[index] = el;
                  }}
                  type="button"
                  role="menuitemradio"
                  aria-checked={w.id === ws}
                  className="eos-ws-option"
                  onKeyDown={(event) => onOptionKey(event, index)}
                  onClick={() => {
                    setWs(w.id);
                    setMenu(false);
                    wsButton.current?.focus();
                  }}
                >
                  {w.mark}
                  {w.name}
                  {w.id === ws && <RiCheckLine size={16} aria-hidden />}
                </button>
              ))}
            </div>
          )}
        </div>
        <div className="eos-side-tools">
          <button type="button" className="eos-icon-btn" aria-label="Search" aria-expanded={query !== null} onClick={() => setQuery((q) => (q === null ? "" : null))}>
            <RiSearchLine size={18} />
          </button>
          {onCollapse && (
            <button type="button" className="eos-icon-btn" aria-label={collapseLabel} onClick={onCollapse}>
              <RiSideBarLine size={18} />
            </button>
          )}
        </div>
      </div>
      {query !== null && (
        <input
          className="eos-side-search"
          type="search"
          placeholder="Search"
          aria-label="Search the sidebar"
          value={query}
          autoFocus
          onChange={(event) => setQuery(event.target.value)}
        />
      )}
      <EosSegmentedControl
        segments={tabs}
        value={view}
        onChange={(next) => {
          setSwitched(true);
          setView(next);
        }}
        block
        size="sm"
        label="Sidebar view"
      />
      {view === tabs[0]?.value ? (
        <nav ref={nav} className="eos-nav" aria-label="Main">
          <EosIndicator ref={navActive} />
          {shown.map((section) => (
            // Staggered by its place among all sections, so a search narrowing the list never changes a delay.
            <div key={section.id} {...rise(sections.findIndex((s) => s.id === section.id))}>
              {section.label && <p className="eos-nav-label">{section.label}</p>}
              <ul className="eos-nav-list">
                {section.items.map((item) => {
                  const on = item.id === current;
                  const inner = (
                    <>
                      <span className="eos-nav-icon">{item.icon}</span>
                      <span className="eos-nav-text">{item.label}</span>
                      {badge(item)}
                    </>
                  );
                  return (
                    <li key={item.id}>
                      {item.href ? (
                        <a ref={row(item.id)} className="eos-nav-item" href={item.href} aria-current={on ? "page" : undefined} onClick={() => setCurrent(item.id)}>
                          {inner}
                        </a>
                      ) : (
                        <button ref={row(item.id)} type="button" className="eos-nav-item" aria-current={on ? "page" : undefined} onClick={() => setCurrent(item.id)}>
                          {inner}
                        </button>
                      )}
                    </li>
                  );
                })}
              </ul>
            </div>
          ))}
        </nav>
      ) : (
        <ul className="eos-activity" aria-label="Recent activity">
          {activity.map((item, index) => (
            <li key={item.id} {...rise(index)}>
              <EosAppGlyph app={item.app} size={22} />
              <span>{item.text}</span>
              <time>{item.time}</time>
            </li>
          ))}
        </ul>
      )}
    </div>
    </EosScope>
  );
}

export interface EosAppShellProps extends Omit<EosAppSidebarProps, "onCollapse" | "collapseLabel" | "onEscape" | "className" | "style"> {
  title?: string;
  titleIcon?: ReactNode;
  /** Dark by default: the Eos shell is charcoal. */
  mode?: EosMode;
  /** A fixed height scrolls the content inside; "auto" lets the page scroll and keeps the sidebar in view. */
  height?: number | string;
  /** Below this width of its own the sidebar becomes a drawer. */
  compactAt?: number;
  /**
   * The sidebar and top bar. Off, the shell keeps only its content, still mounted, for a page that already shows the
   * app's sidebar around it.
   */
  chrome?: boolean;
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

export function EosAppShell({
  workspaces = EOS_SHELL_WORKSPACES,
  workspace,
  defaultWorkspace,
  onWorkspaceChange,
  onNavigate,
  title = "Routines",
  titleIcon = <RiFlashlightLine size={18} />,
  mode = "dark",
  height = 720,
  compactAt = 720,
  chrome = true,
  children,
  className,
  style,
  ...sidebar
}: EosAppShellProps) {
  const [ws, setWs] = useControlled(workspace, defaultWorkspace ?? workspaces[0]?.id ?? "", onWorkspaceChange);
  const [collapsed, setCollapsed] = useState(false);
  const [drawer, setDrawer] = useState(false);
  const [compact, setCompact] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const side = useRef<HTMLElement>(null);
  const main = useRef<HTMLDivElement>(null);
  const menuButton = useRef<HTMLButtonElement>(null);
  const look = useEosTheme()?.look;
  const ids = useId();
  const sideId = `${ids}-side`;
  const chosen = workspaces.find((w) => w.id === ws) ?? workspaces[0];

  useEffect(() => {
    const el = root.current;
    if (!el || typeof ResizeObserver !== "function") return;
    const ro = new ResizeObserver(([entry]) => setCompact((entry?.contentRect.width ?? el.clientWidth) <= compactAt));
    ro.observe(el);
    return () => ro.disconnect();
  }, [compactAt]);
  useEffect(() => {
    if (!compact || !chrome) setDrawer(false);
  }, [compact, chrome]);
  // An opened drawer takes focus; closing it returns focus to the menu button.
  useEffect(() => {
    if (compact && drawer) side.current?.querySelector<HTMLElement>("button, a, input")?.focus();
  }, [compact, drawer]);

  // Collapsing slides the sidebar away on its own transition; the main area glides from where it was with FLIP, at the
  // same pace, so the two move as one.
  const shut = collapsed && !compact;
  const left = useRef<{ shut: boolean; x: number } | null>(null);
  useIsoLayoutEffect(() => {
    const el = main.current;
    if (!el) return;
    const x = el.offsetLeft;
    const last = left.current;
    left.current = { shut, x };
    if (!last || last.shut === shut || last.x === x || !eosCanAnimate(el)) return;
    const motion = eosMotion(look);
    el.animate([{ transform: `translateX(${last.x - x}px)` }, { transform: "translateX(0px)" }], { duration: motion.indicator, easing: eosEaseCss(motion.ease) });
  }, [shut, look]);

  const closeDrawer = () => {
    setDrawer(false);
    menuButton.current?.focus();
  };
  const hidden = compact && !drawer;

  return (
    <EosScope mode={mode}>
      <style>{CSS}</style>
      <div
        ref={root}
        className={cx("eos-shell", className)}
        data-height={height === "auto" ? "auto" : "fixed"}
        data-chrome={chrome}
        style={{ height: height === "auto" ? undefined : height, ...style }}
      >
        <div className="eos-shell-grid" data-collapsed={shut} data-drawer={drawer ? "open" : "closed"}>
          {chrome && <button type="button" className="eos-scrim" aria-label="Close menu" tabIndex={-1} onClick={closeDrawer} />}
          {chrome && (
            <aside
              ref={side}
              id={sideId}
              className="eos-side"
              aria-label="Sidebar"
              inert={hidden || (collapsed && !compact)}
              {...(compact && drawer ? { role: "dialog", "aria-modal": true } : {})}
            >
              <EosAppSidebar
                {...sidebar}
                workspaces={workspaces}
                workspace={ws}
                onWorkspaceChange={setWs}
                onNavigate={(id) => {
                  onNavigate?.(id);
                  if (compact) closeDrawer();
                }}
                onCollapse={() => (compact ? closeDrawer() : setCollapsed(true))}
                collapseLabel={compact ? "Close menu" : "Collapse sidebar"}
                onEscape={compact && drawer ? closeDrawer : undefined}
              />
            </aside>
          )}
          <div ref={main} className="eos-main">
            {chrome && (
              <header className="eos-top">
                <button
                  ref={menuButton}
                  type="button"
                  className="eos-icon-btn eos-top-menu"
                  aria-label="Open menu"
                  aria-expanded={drawer}
                  aria-controls={sideId}
                  onClick={() => setDrawer(true)}
                >
                  <RiMenuLine size={20} />
                </button>
                <button type="button" className="eos-icon-btn eos-top-open" aria-label="Open sidebar" onClick={() => setCollapsed(false)}>
                  <RiSideBarLine size={18} />
                </button>
                <span className="eos-top-mark" aria-hidden>
                  {chosen?.mark}
                </span>
                <span className="eos-top-icon" aria-hidden>
                  {titleIcon}
                </span>
                <p className="eos-top-title">{title}</p>
              </header>
            )}
            <div className="eos-content">{children}</div>
          </div>
        </div>
      </div>
    </EosScope>
  );
}
